#pragma scop
{
  const int T = 32; // tile size for cache-friendly column blocks
  int jj, jmax;
  // persistent parallel region over rows
  #pragma omp parallel default(none) shared(A,b,x,y) private(i,j,k,w,jj,jmax)
  {
    for (i = 0; i < _PB_N; i++) {
      /* Sequential factorization of the strict lower part of row i
         and forward substitution for y[i].  Only one thread executes
         this; the implicit barrier at the end of the single makes the
         updated row visible to all threads before the U update. */
      #pragma omp single
      {
        for (j = 0; j < i; j++) {
          w = A[i][j];
          #pragma omp simd reduction(-:w)
          for (k = 0; k < j; k++) {
            w -= A[i][k] * A[k][j];
          }
          A[i][j] = w / A[j][j];
        }

        w = b[i];
        #pragma omp simd reduction(-:w)
        for (j = 0; j < i; j++) {
          w -= A[i][j] * y[j];
        }
        y[i] = w;
      } /* implicit barrier */

      /* Parallel update of the upper part of row i.
         Tile the column dimension to improve reuse of the trailing
         matrix block while keeping contiguous accesses. */
      #pragma omp for schedule(static) private(j,jj,k,w,jmax)
      for (jj = i; jj < _PB_N; jj += T) {
        jmax = (jj + T < _PB_N) ? jj + T : _PB_N;
        for (j = jj; j < jmax; j++) {
          w = A[i][j];
          #pragma omp simd reduction(-:w)
          for (k = 0; k < i; k++) {
            w -= A[i][k] * A[k][j];
          }
          A[i][j] = w;
        }
      }
    }
  }

  /* Back substitution: inherently sequential from bottom to top. */
  for (i = _PB_N - 1; i >= 0; i--) {
    w = y[i];
    #pragma omp simd reduction(-:w)
    for (j = i + 1; j < _PB_N; j++) {
      w -= A[i][j] * x[j];
    }
    x[i] = w / A[i][i];
  }
}
#pragma endscop

