#pragma scop
{
  const int T = 32;
  int jj, kk, jmax, kmax;

  #pragma omp parallel default(shared) private(i, j, k, w, jj, kk, jmax, kmax)
  {
    for (i = 0; i < _PB_N; i++) {
      #pragma omp single
      {
        /* Strict lower factorization of row i with column tiling. */
        for (jj = 0; jj < i; jj += T) {
          jmax = (jj + T < i) ? jj + T : i;
          for (j = jj; j < jmax; j++) {
            w = A[i][j];
            #pragma omp simd reduction(-:w)
            for (k = 0; k < j; k++) {
              w -= A[i][k] * A[k][j];
            }
            A[i][j] = w / A[j][j];
          }
        }

        /* Forward substitution for y[i], fused with factorization. */
        w = b[i];
        #pragma omp simd reduction(-:w)
        for (j = 0; j < i; j++) {
          w -= A[i][j] * y[j];
        }
        y[i] = w;
      } /* end single -- implicit barrier */

      /* Parallel upper update of row i with 2-D tiling. */
      #pragma omp for schedule(static)
      for (jj = i; jj < _PB_N; jj += T) {
        jmax = (jj + T < _PB_N) ? jj + T : _PB_N;
        for (j = jj; j < jmax; j++) {
          w = A[i][j];
          for (kk = 0; kk < i; kk += T) {
            kmax = (kk + T < i) ? kk + T : i;
            #pragma omp simd reduction(-:w)
            for (k = kk; k < kmax; k++) {
              w -= A[i][k] * A[k][j];
            }
          }
          A[i][j] = w;
        }
      }
    }
  }

  for (i = _PB_N - 1; i >= 0; i--) {
    w = y[i];
    #pragma omp simd reduction(-:w)
    for (j = i + 1; j < _PB_N; j++) {
      w -= A[i][j] * x[j];
    }
    x[i] = w / A[i][i];
  }
}
